<div class="-m-4 flex min-h-[calc(100vh-4rem)] flex-col sm:-m-6 lg:-m-8" x-data="{ previewSrc: @js($previewUrl) }" x-on:theme-preview-refresh.window="previewSrc = $event.detail.url + '&refresh=' + Date.now()">
    <header class="flex flex-wrap items-center justify-between gap-3 border-b border-zinc-200 bg-white px-5 py-3 dark:border-zinc-800 dark:bg-zinc-950"><flux:button type="button" wire:click="leaveEditor" variant="ghost" icon="arrow-left">Back to themes</flux:button><div class="flex items-center gap-2"><x-admin.status-badge :status="$theme->status" /><flux:button type="button" wire:click="save">Save</flux:button><flux:button type="button" wire:click="publish" variant="primary">Save and publish</flux:button></div></header>
    <div class="grid min-h-0 flex-1 lg:grid-cols-[264px_minmax(360px,1fr)_320px]">
