        <main class="min-h-[36rem] bg-zinc-100 p-5 dark:bg-zinc-900"><div class="h-full overflow-hidden rounded-2xl border border-zinc-300 bg-white shadow-sm dark:border-zinc-700"><iframe x-bind:src="previewSrc" title="Storefront theme preview" class="h-full min-h-[36rem] w-full"></iframe></div></main>
        <aside class="border-l border-zinc-200 bg-white p-5 dark:border-zinc-800 dark:bg-zinc-950">
