                @if($field['type'] === 'checkbox')<x-admin.switch :checked="(bool)$value" :label="$field['label']" wire:change="updateSetting('{{ $key }}', $event.target.checked)" />
                @elseif($field['type'] === 'textarea')<flux:textarea :value="$value" :label="$field['label']" rows="3" wire:change="updateSetting('{{ $key }}', $event.target.value)" />
                @elseif($field['type'] === 'select')<flux:select :label="$field['label']" wire:change="updateSetting('{{ $key }}', $event.target.value)">@foreach($field['options'] as $optionValue => $optionLabel)<flux:select.option :value="$optionValue" :selected="$value === $optionValue">{{ $optionLabel }}</flux:select.option>@endforeach</flux:select>
                @elseif($field['type'] === 'color')<label class="block text-sm font-medium text-zinc-700 dark:text-zinc-200">{{ $field['label'] }}<span class="mt-2 flex items-center gap-3"><input type="color" value="{{ $value }}" wire:change="updateSetting('{{ $key }}', $event.target.value)" class="h-10 w-16 rounded border"><span class="font-mono text-xs">{{ $value }}</span></span></label>
                @else<flux:input :value="$value" :label="$field['label']" wire:change="updateSetting('{{ $key }}', $event.target.value)" />@endif
            @endforeach</div>@else<div class="grid h-full place-items-center text-center text-sm text-zinc-500">Select a section to edit its settings.</div>@endif
        </aside>
    </div>
